\begin{tikzpicture}[font=\sffamily, scale=1]

  % --- Cliff drawing ---
  % Vertical cliff on the left, jagged near the top
  \draw[thick] (0, 4.5) -- (0, -3.5);
  % Add surface hatch marks on the left side of x=0 (inside the rock)
  \foreach \y in {-3.2, -2.8, ..., 4.2} {
    \draw (\0, \y) -- (-0.3, \y + 0.3);
  }
  % Make the top jagged
  \draw[thick] (0, 4.5) -- (-0.2, 4.8) -- (0.1, 5.2) -- (-0.5, 5.6) -- (0, 6.0);
  \node[above right] at (0, 5.5) {cliff};

  % --- Rope ---
  \draw[thick] (0, 5.8) -- (1.5, 2.0);
  \node[above] at (0.8, 4.2) {rope};

  % --- Rock Climber ---
  % Hands holding rope at (1.5, 2.0)
  % Feet on cliff at (0, 0.5)
  % Centre of gravity dot roughly in the middle of the torso
  \coordinate (feet) at (0, 0.5);
  \coordinate (hands) at (1.5, 2.0);
  \coordinate (cog) at (1.1, 1.2);
  \coordinate (head) at (1.8, 2.6);
  \coordinate (hips) at (0.8, 0.3);

  % Body parts (stick-figure style with body thickness, or simplified shapes)
  % Let's draw a simplified outline of a climber leaning back

  % Head
  \draw[thick, fill=white] (head) circle (0.3);

  % Torso & Limbs
  % Straight legs from feet to hips
  \draw[thick] (feet) -- (hips);
  % Torso from hips to head/hands
  \draw[thick] (hips) -- (1.5, 2.0);
  % Arms
  \draw[thick] (hands) -- (1.6, 2.2); % holding rope
  % Helmet/Hair detail or just simple head is fine.

  % Centre of gravity dot
  \fill (cog) circle (2pt);
  \node[above left] at (cog) {centre of gravity};

  % Climber label
  \node[right] at (2.2, 1.0) {rock climber};

  % --- Caption ---
  \node[below, align=center] at (1.0, -4.2) {Fig. 2.1};

\end{tikzpicture}

